/* Generated by scripts/catalogue — do not edit. Run `npm run catalogue`. */
import data from './catalogue.slim.json';

/**
 * What a facet UI needs and nothing more: one row per listable piece, short keys, about
 * 136 kB raw. This is the only catalogue data the browser is ever sent, and it is
 * imported lazily — when the concierge opens or a department mounts, never in the base bundle.
 */
export interface SlimProduct {
  /** slug */ s: string;
  /** title */ t: string;
  /** departments */ d: string[];
  /** category */ c?: string;
  /** material */ m?: string;
  /** purity */ k?: string;
  /** gross weight, grams */ w?: number;
  /** diamond carat */ ct?: number;
  /** occasions */ o: string[];
  /** campaign */ cp?: string;
  /** price in PKR, 0 when on request */ p: number;
  /** hero: an asset id when local, a source url when remote */ h: string;
  /** hero width, remote only */ hw?: number;
  /** hero height, remote only */ hh?: number;
}

export const SLIM_PRODUCTS = data.products as SlimProduct[];
export const SLIM_SYNCED_AT = data.syncedAt;
